import json
import os

# Constants
PREFIXES = ["is_", "has_", "can_", "should_"]

def task_func(directory):
    """
    Reads all JSON files from the specified directory, counts the occurrence of keys 
    starting with certain prefixes (defined in the PREFIXES constant), and returns a dictionary 
    of statistics.

    Parameters:
    - directory (str): The path to the directory containing JSON files.

    Returns:
    - dict: A dictionary with keys as prefixes (from PREFIXES) and values as their counts 
            across all JSON files in the directory.

    Raises:
    - FileNotFoundError: If the specified directory does not exist.
    - ValueError: If the directory contains no JSON files.
    """
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"The directory '{directory}' does not exist.")
    json_files = [f for f in os.listdir(directory) if f.endswith('.json')]
    if not json_files:
        raise ValueError(f"No JSON files found in directory '{directory}'.")
    stats = {prefix: 0 for prefix in PREFIXES}
    for file_name in json_files:
        file_path = os.path.join(directory, file_name)
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, dict):
                keys = data.keys()
            elif isinstance(data, list):
                keys = set()
                for item in data:
                    if isinstance(item, dict):
                        keys.update(item.keys())
            else:
                continue
            for key in keys:
                if isinstance(key, str):
                    for prefix in PREFIXES:
                        if key.startswith(prefix):
                            stats[prefix] += 1
        except (json.JSONDecodeError, UnicodeDecodeError):
            continue
    return stats
